```yaml
name: Weekly Repo Status

on:
  schedule:
    # Runs every Sunday at 00:00 UTC
    - cron: '0 0 * * 0'

permissions:
  contents: read
  issues: write

jobs:
  report:
    runs-on: ubuntu-latest
    steps:
      - name: Generate weekly status
        uses: actions/github-script@v6
        with:
          script: |
            const { owner, repo } = context.repo;
            const now = new Date();
            const start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            const end = now;

            // Helper to format dates
            const formatDate = d => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

            // Fetch merged PRs in the last week
            const mergedPRs = await github.paginate(
              github.rest.pulls.list,
              { owner, repo, state: 'closed', sort: 'updated', direction: 'desc', per_page: 100 },
              response => response.data.filter(pr => pr.merged_at && new Date(pr.merged_at) >= start && new Date(pr.merged_at) < end)
            );

            // Fetch closed issues in the last week
            const closedIssues = await github.paginate(
              github.rest.issues.listForRepo,
              { owner, repo, state: 'closed', per_page: 100 },
              response => response.data.filter(issue => !issue.pull_request && new Date(issue.closed_at) >= start && new Date(issue.closed_at) < end)
            );

            // Fetch opened issues in the last week
            const openedIssues = await github.paginate(
              github.rest.issues.listForRepo,
              { owner, repo, state: 'open', per_page: 100 },
              response => response.data.filter(issue => !issue.pull_request && new Date(issue.created_at) >= start && new Date(issue.created_at) < end)
            );

            // Build the body of the status issue
            const body = `
**Weekly Repo Status — ${formatDate(start)}–${formatDate(end)}, ${now.getFullYear()}**

### 📊 Issues This Week

#### Issues Opened: ${openedIssues.length}
${openedIssues.map(i => `- [#${i.number}](${i.html_url})`).join('\n')}

#### Issues Closed: ${closedIssues.length}
${closedIssues.map(i => `- [#${i.number}](${i.html_url})`).join('\n')}

### 🚀 PRs Merged: ${mergedPRs.length}
${mergedPRs.map(pr => `- [#${pr.number}](${pr.html_url})`).join('\n')}
`;

            const issueTitle = `Weekly Repo Status — ${formatDate(start)}–${formatDate(end)}, ${now.getFullYear()}`;

            // Check if an issue with this title already exists
            const existing = await github.paginate(
              github.rest.issues.listForRepo,
              { owner, repo, state: 'open', labels: 'weekly-status', per_page: 100 },
              response => response.data
            ).then(issues => issues.find(i => i.title === issueTitle));

            if (existing) {
              // Update the existing issue
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: existing.number,
                body,
                labels: ['weekly-status']
              });
            } else {
              // Create a new issue
              await github.rest.issues.create({
                owner,
                repo,
                title: issueTitle,
                body,
                labels: ['weekly-status']
              });
            }
          env:
            GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
```

